def count_regions(grid):
    def dfs(r, c, visited):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) not in visited:
                visited.add((x, y))
                for nr, nc in neighbors(grid, x, y):
                    if grid[nr][nc] == '.' and (nr, nc) not in visited:
                        stack.append((nr, nc))

    visited = set()
    region_count = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == '.' and (r, c) not in visited:
                dfs(r, c, visited)
                region_count += 1
    return region_count
```

