function formatMoney(cents, code = 'USD') {
    const dollars = Math.abs(cents) / 100;
    let formatted;
    if (code === 'USD') {
        formatted = dollars.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
    } else if (code === 'EUR') {
        formatted = dollars.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
    } else if (code === 'GBP') {
        formatted = dollars.toLocaleString('en-GB', { style: 'currency', currency: 'GBP' });
    } else {
        formatted = `${code} ${dollars.toLocaleString('en-US', { minimumFractionDigits: 2 })}`;
    }
    return cents < 0 ? '-' + formatted : formatted;
}
```

