class TaskGraph {
  constructor() {
    this.tasks = new Map();
    this.dependencies = new Map();
    this.completed = new Set();
  }

  ready(doneIds) {
    const readyTasks = [];
    for (const [id, dependencies] of this.dependencies) {
      if (!doneIds.includes(id) && dependencies.every(dep => doneIds.includes(dep))) {
        readyTasks.push(id);
      }
    }
    return readyTasks;
  }
```

